// Lookup route handlers for external service lookups.
import { jsonResponse, parseQuery, routeNotFound } from './response.js';

async function ipLookup(ipOrHost) {
  try {
    const res = await fetch(`http://ip-api.com/json/${encodeURIComponent(ipOrHost)}?fields=status,message,country,countryCode,region,regionName,city,zip,lat,lon,timezone,isp,org,as,query`);
    if (!res.ok) return null;
    const data = await res.json();
    if (data && data.status === 'success') return data;
    return null;
  } catch (e) {
    return null;
  }
}

export async function lookupHandler(parts, request, env) {
  const endpoint = parts[0] || '';
  const q = parseQuery(request);

  if (endpoint === 'lookup_fivem') {
    const code = q.cfx_code || q.code;
    if (!code) return jsonResponse({ error: true, message: 'missing cfx_code' }, 400);
    try {
      const res = await fetch(`https://servers-frontend.fivem.net/api/servers/single/${encodeURIComponent(code)}`);
      if (!res.ok) throw new Error('lookup failed');
      const data = await res.json();
      return jsonResponse({ error: false, server: data, ip_info: data?.endpoint ? await ipLookup(data.endpoint) : null });
    } catch (e) {
      return jsonResponse({ error: true, message: 'fivem lookup failed', detail: e.message }, 502);
    }
  }

  if (endpoint === 'lookup_mc') {
    const addr = q.server_address || q.address;
    if (!addr) return jsonResponse({ error: true, message: 'missing server_address' }, 400);
    try {
      const res = await fetch(`https://api.mcsrvstat.us/2/${encodeURIComponent(addr)}`);
      if (!res.ok) throw new Error('mc lookup failed');
      const data = await res.json();
      return jsonResponse({ error: false, server: data, ip_info: data?.ip ? await ipLookup(data.ip) : null });
    } catch (e) {
      return jsonResponse({ error: true, message: 'mc lookup failed', detail: e.message }, 502);
    }
  }

  return routeNotFound();
}
